createApp({
  data: () => ({ email:'', password:'', showPassword:false, isSubmitting:false, formError:'', authenticated:false, sessionReady:false, selectingCompany:false, isSelectingCompany:false, companyError:'', companies:[], activeCompany:null, roles:[], activeRole:null, isSelectingRole:false, sidebarOpen:false, modules, catalogs, expandedModules:[], currentModule:'CORE', currentSection:'CORE', userName:'equipo', search:'', rows:[], referenceOptions:{}, tableError:'', tableLoading:false, dialogSaving:false, dialogError:'', recordDialog:{open:false,mode:'form',id:null,values:{},label:''} }),
  mounted() { void this.restoreSession(); },
  computed: {
    activeCatalog() { return this.catalogs.find(catalog => catalog.title === this.currentSection) ?? null; },
    filteredRows() { const term=this.search.trim().toLocaleLowerCase('es'); return term ? this.rows.filter(row => Object.values(row).some(value => String(value ?? '').toLocaleLowerCase('es').includes(term))) : this.rows; },
    userInitial() { return this.userName.charAt(0).toUpperCase(); },
    activeModuleIcon() { return this.modules.find(module => module.name === this.currentModule)?.icon ?? icons.core; }
  },
  methods: {
    token() { return localStorage.getItem('nexo_token')??sessionStorage.getItem('nexo_token'); },
    async restoreSession(){try{const token=this.token();if(!token)return;const encoded=token.split('.')[1];if(!encoded)throw new Error('Sesión inválida.');const payload=JSON.parse(atob(encoded.replace(/-/g,'+').replace(/_/g,'/')));if(Number(payload.exp??0)*1000<=Date.now())throw new Error('La sesión expiró.');this.userName=String(payload.email??'equipo').split('@')[0];this.authenticated=true;this.roles=await this.api('/api/auth/roles');if(!this.roles.length)throw new Error('El usuario no tiene roles asignados.');const storedRole=localStorage.getItem('nexo_role')??sessionStorage.getItem('nexo_role');const role=this.roles.find(item=>String(item.roleId)===storedRole)??this.roles.find(item=>item.name.toLowerCase()==='administrador')??this.roles[0];await this.selectRole(role,false);this.companies=await this.api('/api/auth/companies');if(!this.companies.length)throw new Error('El usuario no tiene empresas asignadas.');const storedCompany=localStorage.getItem('nexo_company')??sessionStorage.getItem('nexo_company');const company=this.companies.find(item=>String(item.subsidiaryId)===storedCompany);if(company)await this.selectCompany(company);else if(this.companies.length===1)await this.selectCompany(this.companies[0]);else this.selectingCompany=true;}catch{this.logout();}finally{this.sessionReady=true;}},
    async signIn() { this.formError=''; this.isSubmitting=true; try { const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:this.email,password:this.password})}); const data=await response.json(); if(!response.ok) throw new Error(data.error?.message||'No fue posible iniciar sesión.'); localStorage.setItem('nexo_token',data.accessToken); this.userName=data.user.name; this.authenticated=true; this.roles=await this.api('/api/auth/roles'); if(!this.roles.length)throw new Error('El usuario no tiene roles asignados.');const initialRole=this.roles.find(role=>role.name.toLowerCase()==='administrador')??this.roles[0];await this.selectRole(initialRole,false);this.companies=await this.api('/api/auth/companies'); if(!this.companies.length)throw new Error('El usuario no tiene empresas asignadas.'); if(this.companies.length===1)await this.selectCompany(this.companies[0]);else this.selectingCompany=true; } catch(cause){this.authenticated=false;localStorage.removeItem('nexo_token');sessionStorage.removeItem('nexo_token');this.formError=cause instanceof Error?cause.message:'No fue posible iniciar sesión.';} finally{this.isSubmitting=false;this.sessionReady=true;} },
    async selectRole(role,reload=true){this.isSelectingRole=true;try{this.activeRole=await this.api('/api/auth/select-role',{method:'POST',body:JSON.stringify({roleId:role.roleId})});localStorage.setItem('nexo_role',String(role.roleId));this.rows=[];this.referenceOptions={};if(reload&&this.activeCompany)await this.loadCatalog();}finally{this.isSelectingRole=false;}},
    async changeRole(event){const role=this.roles.find(item=>String(item.roleId)===String(event.target.value));if(!role)return;try{await this.selectRole(role,true);}catch(cause){this.tableError=cause instanceof Error?cause.message:'No fue posible cambiar el rol.';}},
    async chooseRole(role,event){event.currentTarget.closest('details')?.removeAttribute('open');if(String(role.roleId)===String(this.activeRole?.roleId))return;try{await this.selectRole(role,true);}catch(cause){this.tableError=cause instanceof Error?cause.message:'No fue posible cambiar el rol.';}},
    async selectCompany(company) { this.companyError='';this.isSelectingCompany=true;try{this.activeCompany=await this.api('/api/auth/select-company',{method:'POST',body:JSON.stringify({subsidiaryId:company.subsidiaryId})});localStorage.setItem('nexo_company',String(company.subsidiaryId));this.selectingCompany=false;this.rows=[];this.referenceOptions={};await this.loadCatalog();}catch(cause){this.companyError=cause instanceof Error?cause.message:'No fue posible seleccionar la empresa.';}finally{this.isSelectingCompany=false;} },
    changeCompany() { if(this.companies.length>1){this.selectingCompany=true;this.companyError='';this.rows=[];} },
    async chooseCompany(company,event){event.currentTarget.closest('details')?.removeAttribute('open');if(String(company.subsidiaryId)===String(this.activeCompany?.subsidiaryId))return;await this.selectCompany(company);},
    async api(path,init={}) { const response=await fetch(path,{...init,headers:{...(init.body?{'Content-Type':'application/json'}:{}),Authorization:`Bearer ${this.token()}`,...(init.headers??{})}}); const data=await response.json(); if(!response.ok) throw new Error(data.error?.message||'No fue posible completar la operación.'); return data; },
    catalogPath(catalog=this.activeCatalog) { return `/api/${catalog.apiRoot??'core'}/${catalog.slug}`; },
    async loadCatalog() { if(!this.activeCatalog)return; this.tableLoading=true; this.tableError=''; try{this.rows=await this.api(this.catalogPath()); await this.loadReferenceOptions();}catch(cause){this.tableError=cause instanceof Error?cause.message:'No fue posible consultar el catálogo.';}finally{this.tableLoading=false;} },
    async loadReferenceOptions() { const references=[...new Set(this.activeCatalog.fields.map(field=>field.reference).filter(Boolean))]; await Promise.all(references.map(async reference=>{this.referenceOptions[reference]=await this.api(`/api/${reference}`);})); },
    selectModule(module) { this.currentModule=module.name; this.currentSection=module.name; this.search=''; if(module.children){const index=this.expandedModules.indexOf(module.name); if(index>=0)this.expandedModules.splice(index,1);else this.expandedModules.push(module.name);} this.sidebarOpen=false; },
    navigateChild(module,child) { this.currentModule=module; this.currentSection=child; this.search=''; this.rows=[]; this.sidebarOpen=false; void this.loadCatalog(); },
    displayValue(field,value) { if(field.type==='boolean') return value?'Sí':'No'; if(field.type==='password') return value?'••••••••':'—'; if(field.type==='multi-reference'){return (value??[]).map(id=>{const option=(this.referenceOptions[field.reference]??[]).find(row=>String(this.referenceId(field.reference,row))===String(id));return option?this.referenceLabel(option):`#${id}`;}).join(', ')||'—';} if(field.reference&&value!==null&&value!==undefined){const option=(this.referenceOptions[field.reference]??[]).find(row=>String(this.referenceId(field.reference,row))===String(value));return option?this.referenceLabel(option):`#${value}`;} return value??'—'; },
    recordLabel(row) { const field=this.activeCatalog.fields.find(item=>item.key==='name')??this.activeCatalog.fields[0]; return String(row[field.key]??`#${row[this.activeCatalog.primaryKey]}`); },
    async openRecordForm(row=null) { const values={}; for(const field of this.activeCatalog.fields){const fallback=field.type==='boolean'?true:(field.type==='multi-reference'?[]:'');const value=row?.[field.key]??fallback;values[field.key]=field.type==='datetime-local'&&value?String(value).slice(0,16):value;} this.dialogError=''; this.recordDialog={open:true,mode:'form',id:row?.[this.activeCatalog.primaryKey]??null,values,label:row?this.recordLabel(row):''}; await this.$nextTick(); document.querySelectorAll('.modal input[type="number"]').forEach(input=>input.setAttribute('step','any')); await this.loadReferenceOptions().catch(cause=>{this.dialogError=cause instanceof Error?cause.message:'No fue posible cargar las opciones.';}); },
    allReferenceSelected(field) { const options=this.referenceOptions[field.reference]??[]; return options.length>0&&this.recordDialog.values[field.key]?.length===options.length; },
    toggleAllReferences(field) { const options=this.referenceOptions[field.reference]??[]; this.recordDialog.values[field.key]=this.allReferenceSelected(field)?[]:options.map(option=>this.referenceId(field.reference,option)); },
    referenceCatalog(reference) { const [apiRoot,slug]=reference.split('/'); return this.catalogs.find(catalog=>(catalog.apiRoot??'core')===apiRoot&&catalog.slug===slug); },
    referenceId(reference,row) { return row[this.referenceCatalog(reference).primaryKey]; },
    referenceLabel(row) { return String(row.name??row.so_number??row.po_number??row.invoice_number??row.journal_number??row.tran_number??row.list_name??row.display_name??row.category_name??row.brand_name??row.group_name??row.type_name??row.bin_code??row.zone_name??row.lot_number??row.company_name??([row.first_name,row.last_name].filter(Boolean).join(' ')||null)??row.bank_name??row.account_name??row.account_number??row.budget_name??row.book_name??row.legal_name??row.calendar_name??row.year_name??row.period_name??row.agency_name??row.method_name??row.term_name??row.series_name??row.role_name??row.email??row.title??row.code??row.currency_code??row.device_name??Object.values(row)[1]??'Registro'); },
    requestDelete(row) { this.dialogError=''; this.recordDialog={open:true,mode:'delete',id:row[this.activeCatalog.primaryKey],values:{},label:this.recordLabel(row)}; },
    closeRecordDialog() { if(!this.dialogSaving)this.recordDialog.open=false; },
    async submitRecord() { this.dialogSaving=true; this.dialogError=''; try{const id=this.recordDialog.id; await this.api(`${this.catalogPath()}${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(this.recordDialog.values)}); this.recordDialog.open=false; await this.loadCatalog();}catch(cause){this.dialogError=cause instanceof Error?cause.message:'No fue posible guardar el registro.';}finally{this.dialogSaving=false;} },
    async confirmDelete() { this.dialogSaving=true; this.dialogError=''; try{await this.api(`${this.catalogPath()}/${this.recordDialog.id}`,{method:'DELETE'}); this.recordDialog.open=false; await this.loadCatalog();}catch(cause){this.dialogError=cause instanceof Error?cause.message:'No fue posible eliminar el registro.';}finally{this.dialogSaving=false;} },
    logout() { for(const key of['nexo_token','nexo_company','nexo_role']){localStorage.removeItem(key);sessionStorage.removeItem(key);}this.authenticated=false;this.selectingCompany=false;this.activeCompany=null;this.companies=[];this.activeRole=null;this.roles=[];this.password='';this.formError='';this.expandedModules=[];this.currentModule='CORE';this.currentSection='CORE';this.rows=[]; }
  }
}).mount('#app');
